function pBooksLoad(child){ var box=$("pBooks"); if(!box) return; api("/api/parent/books?child="+child).then(function(d){ if(!d.state||d.state.state==="off"){ box.innerHTML=""; return; } BK.p=d; BK.pc=child; pBooksDraw(); }).catch(function(){ box.innerHTML=""; }); }
function pBooksDraw(){ var box=$("pBooks"), d=BK.p, s=d.state, first=String(d.name||"").split(" ")[0], R=d.reads||[], wk=R.filter(function(r){ return r.date>=addDaysStr(-6); });
  var mins=Math.round(wk.reduce(function(a,r){ return a+(r.secs||0); },0)/60), done=wk.filter(function(r){ return r.done; }).length;
  var h='<div class="card"><div class="row between"><h2>📚 '+tr(first+"-ന്റെ വായന",first+" की पढ़ाई",first+"'s reading")+'</h2>'+(s.parentPick?'<button class="btn ghost sm" id="pBkArr">⭐ '+tr("Shelf ഒരുക്കൂ","Shelf सजाओ","Arrange shelf")+'</button>':'')+'</div>';
  h+='<div class="p-row"><span style="flex:1">'+tr("ഈ ആഴ്ച","इस हफ़्ते","This week")+'</span><b>'+wk.length+' books · '+done+' ✅ · '+mins+' min</b></div>';
  h+='<div class="p-row"><span style="flex:1">'+tr("Ma'am-ന്റെ നിയമം","Ma'am का नियम","Ma'am's rule")+'</span><b class="small">'+(s.state==="notyou"||s.state==="pro"? tr("ഇപ്പോൾ തുറന്നിട്ടില്ല","अभी बंद","Not open yet") : bkT12(s.from)+'–'+bkT12(s.to)+(s.perDay?' · '+s.perDay+' books/day':'')+(s.mins?' · '+s.mins+' min/day':''))+'</b></div>';
  h+=(R.length? R.slice(0,6).map(function(r){ return '<div class="p-row"><span style="font-size:20px">'+esc(r.cover||"📘")+'</span><span style="flex:1"><b>'+esc(r.title)+'</b><div class="small muted">'+gfFmt(r.date)+' · '+Math.max(1,Math.round((r.secs||0)/60))+' min · '+tr("പേജ് ","पेज ","page ")+r.page+'/'+r.pages+'</div></span><b class="small" style="color:'+(r.done?'#1f8a5b':'#5b6472')+'">'+(r.done?'✅'+(r.quiz_total?' '+r.quiz_score+'/'+r.quiz_total:''):'…')+'</b></div>'; }).join("") : '<div class="small muted" style="margin-top:6px">'+tr("ഇതുവരെ വായിച്ചിട്ടില്ല.","अभी तक नहीं पढ़ा।","No reading yet.")+'</div>')+'</div>';
  var FN=d.finished||[]; if(FN.length) h=h.replace(/<\/div>$/,'')+'<details style="margin-top:10px"'+(FN.length<=4?' open':'')+'><summary class="small" style="font-weight:700;cursor:pointer">✅ '+tr("വായിച്ചു തീർത്ത പുസ്തകങ്ങൾ","पूरी पढ़ी किताबें","Books finished")+' ('+FN.length+')</summary>'+FN.map(function(r){ return '<div class="p-row"><span style="font-size:20px">'+esc(r.cover||"📘")+'</span><span style="flex:1"><b>'+esc(r.title)+'</b><div class="small muted">'+gfFmt(r.last)+(r.qt?' · quiz '+r.qs+'/'+r.qt:'')+(r.kind!=="rec"&&r.secs?' · '+Math.max(1,Math.round(r.secs/60))+' min':'')+(r.comment?' · “'+esc(r.comment)+'”':'')+'</div></span>'+(r.stars?'<b class="small" style="color:#b7791f">'+"★★★★★".slice(0,r.stars)+'</b>':'')+'</div>'; }).join("")+'</details></div>';
  var RB=(d.books||[]).filter(function(x){ return x.kind==="rec" && !x.hidden; });
  if(RB.length) h=h.replace(/<\/div>$/,'')+'<div class="small" style="font-weight:700;margin:10px 0 4px">📖 '+tr("Ma\'am നിർദ്ദേശിക്കുന്ന പുസ്തകങ്ങൾ","Ma\'am की सुझाई किताबें","Real books Ma\'am suggests")+'</div>'+RB.map(function(x){ var r=R.filter(function(y){ return y.book_id===x.id && y.done; })[0]; return '<div class="p-row"><span style="font-size:20px">'+esc(x.cover||"📖")+'</span><span style="flex:1"><b>'+esc(x.title)+'</b><div class="small muted">'+(x.author?esc(x.author)+' · ':'')+bkCls(x)+(r?' · ✅ '+tr("വായിച്ചു","पढ़ ली","read"):'')+'</div></span>'+(x.buy?'<a class="btn ghost sm" href="'+esc(x.buy)+'" target="_blank" rel="noopener">🛒</a>':'')+'</div>'; }).join("")+'</div>';
  box.innerHTML=h; if($("pBkArr")) $("pBkArr").onclick=pBooksArrange; }
function pBooksArrange(){ var d=BK.p, picks=d.books.filter(function(x){ return x.pick>0&&!x.hidden; }).sort(function(a,c){ return a.pick-c.pick; }).map(function(x){ return x.id; }), hid=d.books.filter(function(x){ return x.hidden; }).map(function(x){ return x.id; });
  var w=ekSheet("","pBkSheet");
  function draw(){ var by={}; d.books.forEach(function(x){ by[x.id]=x; }); var others=d.books.filter(function(x){ return picks.indexOf(x.id)<0; });
    var row=function(x, i){ var p=picks.indexOf(x.id)>=0, hd=hid.indexOf(x.id)>=0; return '<div class="p-row" style="gap:8px;'+(hd?'opacity:.5':'')+'"><span style="font-size:22px">'+esc(x.cover||"📘")+'</span><span style="flex:1"><b>'+esc(x.title)+'</b><div class="small muted">'+(BK_LANG[x.lang]||"")+' · '+bkCls(x)+(x.locked?' · ⭐ Pro':'')+'</div></span>'+
      (p? '<button class="btn ghost sm" data-up="'+x.id+'"'+(i===0?' disabled':'')+'>↑</button><button class="btn ghost sm" data-dn="'+x.id+'">↓</button><button class="btn ghost sm" data-unpick="'+x.id+'">✕</button>' : '<button class="btn ghost sm" data-pick="'+x.id+'"'+(hd?' disabled':'')+'>⭐</button><button class="btn ghost sm" data-hide="'+x.id+'">'+(hd?'👁️':'🙈')+'</button>')+'</div>'; };
    w.querySelector(".in").innerHTML='<h2 style="margin:0 0 4px">⭐ '+tr("കുട്ടിയുടെ Shelf","बच्चे की Shelf","Your child's shelf")+'</h2><div class="small muted" style="margin-bottom:8px">'+tr("⭐ അമർത്തിയ books ആദ്യം കാണും. 🙈 അമർത്തിയാൽ ആ book കുട്ടിക്ക് കാണില്ല.","⭐ वाली books पहले दिखेंगी। 🙈 दबाने पर वह book नहीं दिखेगी।","⭐ books show first, in your order. 🙈 hides a book from your child.")+'</div>'+
      (picks.length?'<div class="small" style="font-weight:700;margin:6px 0">⭐ '+tr("നിങ്ങളുടെ ക്രമം","आपका क्रम","Your order")+'</div>'+picks.map(function(id,i){ return row(by[id], i); }).join(""):'')+'<div class="small" style="font-weight:700;margin:10px 0 6px">📖 '+tr("മറ്റു books","बाकी books","Other books")+'</div>'+(others.length? others.map(function(x){ return row(x); }).join("") : '<div class="small muted">—</div>')+
      '<button class="btn block" id="pBkSave" style="margin-top:12px">'+tr("സേവ് ചെയ്യൂ","सेव करो","Save")+'</button><button class="btn ghost block" data-x style="margin-top:8px">'+tr("റദ്ദാക്കൂ","रद्द","Cancel")+'</button>';
    var mv=function(id,dir){ var i=picks.indexOf(id), j=i+dir; if(j<0||j>=picks.length) return; picks[i]=picks[j]; picks[j]=id; draw(); };
    w.querySelectorAll("[data-up]").forEach(function(b){ b.onclick=function(){ mv(+b.dataset.up,-1); }; });
    w.querySelectorAll("[data-dn]").forEach(function(b){ b.onclick=function(){ mv(+b.dataset.dn,1); }; });
    w.querySelectorAll("[data-unpick]").forEach(function(b){ b.onclick=function(){ picks.splice(picks.indexOf(+b.dataset.unpick),1); draw(); }; });
    w.querySelectorAll("[data-pick]").forEach(function(b){ b.onclick=function(){ picks.push(+b.dataset.pick); draw(); }; });
    w.querySelectorAll("[data-hide]").forEach(function(b){ b.onclick=function(){ var id=+b.dataset.hide, i=hid.indexOf(id); if(i>=0) hid.splice(i,1); else hid.push(id); draw(); }; });
    $("pBkSave").onclick=function(){ api("/api/parent/books/shelf",{child:BK.pc, picks:picks, hidden:hid}).then(function(){ w.remove(); toast("✅ "+tr("Shelf സേവ് ചെയ്തു","Shelf सेव हुई","Shelf saved")); pBooksLoad(BK.pc); }).catch(function(e){ toast(e.message); }); }; }
  draw(); }

