  a.innerHTML='<div style="display:flex;align-items:center;gap:12px;border-bottom:2px solid #1b2a3d;padding-bottom:10px;margin-bottom:14px"><div class="mark" style="width:44px;height:44px;border-radius:12px;background:#ffe45c;display:flex;align-items:center;justify-content:center;font-weight:900;font-size:26px;color:#1b2a3d">E</div><div><div style="font-size:22px;font-weight:800">Ekanthi — Monthly report card</div><div>'+esc(d.name)+' · '+esc(d.report.cls||"")+' · '+new Date().toLocaleDateString([], {month:"long", year:"numeric"})+'</div></div></div>'+reportHtml(d.report,false);
