// 📌 Study Lock for the parent: start from your own phone, stop, see how each lock ended
function pSLLoad(){ var kid=PC.id; api("/api/parent/studylock?child="+kid).then(function(d){ var b=$("pSL"); if(!b || PC.id!==kid) return; var c=d.cur, first=String((PC.d&&PC.d.name)||"").split(" ")[0];
  var left=c&&c.until? Math.max(0,Math.ceil((Date.parse(c.until)-Date.now())/60000)) : 0;
  var h='<h2>📌 '+tr("സ്റ്റഡി ലോക്ക്","स्टडी लॉक","Study Lock")+'</h2><div class="small muted" style="margin-bottom:8px">'+tr(first+"-ന്റെ ഫോൺ Ekanthi-ൽ മാത്രം — YouTube, Instagram, games ഒന്നും തുറക്കില്ല. സമയം കഴിഞ്ഞാലോ നിങ്ങളുടെ Ekanthi PIN അടിച്ചാലോ മാത്രം തുറക്കും.", first+" का फ़ोन सिर्फ़ Ekanthi में — YouTube, Instagram, games नहीं खुलेंगे। समय खत्म होने पर या आपका Ekanthi PIN डालने पर ही खुलेगा।", first+"'s phone stays inside Ekanthi — no YouTube, Instagram or games. It opens only when the time ends or you type your Ekanthi PIN.")+'</div>';
  if(!d.childOn) h+='<div class="small" style="color:#b45309">'+tr("ഈ കുട്ടിക്ക് ഇത് ഓൺ അല്ല — Ma\'am-നോട് ചോദിക്കൂ.","इस बच्चे के लिए यह चालू नहीं — Ma\'am से पूछें।","Not switched on for this child — ask Ma\'am.")+'</div>';
  else{
    if(c) h+='<div class="p-row" style="background:#eef6ff;border-radius:10px;padding:10px"><span style="flex:1">'+(c.waiting? '⏳ '+tr(first+" Ekanthi തുറക്കുമ്പോൾ തുടങ്ങും ("+c.mins+" min)", first+" के Ekanthi खोलते ही शुरू होगा ("+c.mins+" min)", "Starts when "+first+" opens Ekanthi ("+c.mins+" min)") : '🔒 <b>'+tr("ലോക്ക് ഓൺ","लॉक चालू","Locked")+'</b> · '+left+' min '+tr("ബാക്കി","बाकी","left")+(c.breaks?' · <span style="color:#b91c1c">⚠️ '+c.breaks+'× '+tr("പുറത്ത് പോയി","बाहर गया","came out")+'</span>':''))+'</span><button class="btn ghost sm" id="pSLStop">'+tr("നിർത്തുക","बंद करो","Stop")+'</button></div>';
    else if(d.cfg.remote) h+='<div class="small" style="margin-bottom:4px">'+tr("ഇപ്പോൾ ലോക്ക് ചെയ്യൂ (നിങ്ങളുടെ ഫോണിൽ നിന്ന്):","अभी लॉक करें (अपने फ़ोन से):","Lock now (from your phone):")+'</div><div class="row" style="gap:6px;flex-wrap:wrap">'+[30,45,60,90,120,180].filter(function(m){ return m<=d.cfg.max; }).map(function(m){ return '<button class="dev-chip'+(m===d.cfg.def?' on':'')+'" data-psl="'+m+'">'+m+' min</button>'; }).join("")+'</div>';
    else h+='<div class="small">'+tr("കുട്ടിയുടെ ഫോണിൽ Ekanthi → Home → 📌 Study Lock.","बच्चे के फ़ोन पर Ekanthi → Home → 📌 Study Lock।","On the child's phone: Ekanthi → Home → 📌 Study Lock.")+'</div>';
    if(!d.android) h+='<div class="small" style="color:#b45309;margin-top:8px">📱 '+tr(first+"-ന്റെ ഫോണിൽ Ekanthi Android app വേണം (Play Store). Website-ൽ ഫോൺ ലോക്ക് ചെയ്യാൻ പറ്റില്ല.", first+" के फ़ोन में Ekanthi Android app चाहिए (Play Store)। Website से फ़ोन लॉक नहीं होता।", first+" needs the Ekanthi Android app (Play Store). A website cannot lock a phone.")+'</div>';
    h+='<details style="margin-top:10px"><summary class="small" style="cursor:pointer;font-weight:700">🛠️ '+tr("ഒരു തവണ ചെയ്യേണ്ടത് (കുട്ടിയുടെ ഫോണിൽ)","एक बार करें (बच्चे के फ़ोन में)","One-time setup on the child's phone")+'</summary><ol class="small" style="padding-left:18px;line-height:1.6;margin:6px 0"><li>Settings → Security → <b>App pinning</b> → On</li><li><b>Ask for PIN before unpinning</b> → On — '+tr("ഫോണിന്റെ lock PIN കുട്ടിക്ക് അറിയരുത്.","फ़ोन का lock PIN बच्चे को पता न हो।","keep the phone's lock PIN secret from the child.")+'</li><li>'+tr("കുട്ടി പുറത്ത് പോയാൽ നിങ്ങൾക്കും Ma\'am-നും alert വരും.","बच्चा बाहर गया तो आपको और Ma\'am को alert आएगा।","If the child gets out, you and Ma\'am get an alert.")+'</li><li>'+tr("കൂടുതൽ: Google Family Link-ൽ YouTube / Instagram block ചെയ്യാം, screen time വെക്കാം.","और: Google Family Link से YouTube / Instagram block और screen time तय कर सकते हैं।","Extra: Google Family Link can block YouTube / Instagram and set screen time.")+'</li></ol></details>';
    if(d.history.length) h+='<h3 style="margin:12px 0 4px">'+tr("മുമ്പത്തെ ലോക്കുകൾ","पिछले लॉक","Past locks")+'</h3>'+d.history.filter(function(x){ return x.ended; }).slice(0,8).map(function(x){ return '<div class="p-row"><span class="p-date">'+fmtDate(String(x.created).slice(0,10))+'</span><span style="flex:1">'+x.mins+' min · '+(x.by==="p"?"👨‍👩‍👧":"🧒")+' '+esc(x.byName||"")+'<div class="small muted">'+esc(x.howTxt||"")+(x.breaks?' · <span style="color:#b91c1c">⚠️ '+x.breaks+'× '+tr("പുറത്ത് പോയി","बाहर गया","came out")+'</span>':'')+'</div></span></div>'; }).join("");
  }
  b.innerHTML=h;
  b.querySelectorAll("[data-psl]").forEach(function(x){ x.onclick=function(){ var m=Number(x.dataset.psl); if(!confirm(tr(m+" മിനിറ്റ് Study Lock തുടങ്ങട്ടെ? "+first+" Ekanthi തുറക്കുമ്പോൾ ഫോൺ ലോക്ക് ആകും.","Start "+m+" min Study Lock? It locks when "+first+" opens Ekanthi.","Start a "+m+" min Study Lock? The phone locks when "+first+" opens Ekanthi."))) return; api("/api/parent/studylock/start",{child:kid, mins:m}).then(function(){ toast("📌 "+tr("അയച്ചു","भेजा","Sent")); pSLLoad(); }).catch(function(e){ toast(e.message); }); }; });
  if($("pSLStop")) $("pSLStop").onclick=function(){ if(!confirm(tr("Study Lock നിർത്തട്ടെ?","Study Lock बंद करें?","Stop Study Lock now?"))) return; api("/api/parent/studylock/stop",{child:kid}).then(function(){ toast("🔓 OK"); pSLLoad(); }).catch(function(e){ toast(e.message); }); };
}).catch(function(e){ var b=$("pSL"); if(b) b.innerHTML='<div class="small muted">Study Lock: '+esc(e.message)+'</div>'; }); }

